class MainWindow : public QMainWindow
{
    Q_OBJECT
public:
    explicit MainWindow(QWidget *parent = nullptr);

private:
    void onScanClicked();

    QLineEdit *m_pathEdit;
    QPushButton *m_scanButton;
    QLabel *m_statusLabel;
};

#include "mainwindow.h"

#include "scan/scanner.h"

void MainWindow::onScanClicked()
{
    const QString dir = m_pathEdit->text();
    m_statusLabel->setText(tr("Scanning..."));
    const ScanResult result = scanDirectory(dir);
    m_statusLabel->setText(tr("%1 files, %2 duplicates").arg(result.files).arg(result.duplicates));
}

#pragma once

#include <QString>

struct ScanResult {
    int files = 0;
    int duplicates = 0;
};

ScanResult scanDirectory(const QString &dir);

#include "scanner.h"

#include <QCryptographicHash>
#include <QDirIterator>
#include <QFile>
#include <QSet>

ScanResult scanDirectory(const QString &dir)
{
    QSet<QByteArray> seen;
    ScanResult result;
    QDirIterator it(dir, QDir::Files, QDirIterator::Subdirectories);
    while (it.hasNext()) {
        QFile file(it.next());
        if (!file.open(QIODevice::ReadOnly))
            continue;
        QCryptographicHash hash(QCryptographicHash::Sha256);
        hash.addData(&file);
        const QByteArray digest = hash.result();
        ++result.files;
        if (seen.contains(digest))
            ++result.duplicates;
        else
            seen.insert(digest);
    }
    return result;
}

