#include "mainwindow.h"

#include <QFutureWatcher>
#include <QtConcurrent/QtConcurrentRun>

#include "scan/scanner.h"

void MainWindow::onScanClicked()
{
    const QString dir = m_pathEdit->text();
    m_scanButton->setEnabled(false);
    m_statusLabel->setText(tr("Scanning..."));

    QFutureWatcher<ScanResult> watcher;
    connect(&watcher, &QFutureWatcherBase::finished, this, [this, &watcher] {
        const ScanResult result = watcher.result();
        m_statusLabel->setText(tr("%1 files, %2 duplicates").arg(result.files).arg(result.duplicates));
        m_scanButton->setEnabled(true);
    });
    watcher.setFuture(QtConcurrent::run([dir] { return scanDirectory(dir); }));
}

void scanDirectory(QPromise<ScanResult> &promise, const QString &dir)
{
    QStringList paths;
    QDirIterator it(dir, QDir::Files, QDirIterator::Subdirectories);
    while (it.hasNext())
        paths << it.next();
    promise.setProgressRange(0, int(paths.size()));

    QSet<QByteArray> seen;
    ScanResult result;
    for (qsizetype i = 0; i < paths.size(); ++i) {
        if (promise.isCanceled())
            return;
        promise.setProgressValue(int(i + 1));

        QFile file(paths[i]);
        if (!file.open(QIODevice::ReadOnly))
            continue;
        QCryptographicHash hash(QCryptographicHash::Sha256);
        hash.addData(&file);
        const QByteArray digest = hash.result();
        ++result.files;
        if (seen.contains(digest))
            ++result.duplicates;
        else
            seen.insert(digest);
    }
    promise.addResult(result);
}

void MainWindow::onScanClicked()
{
    const QString dir = m_pathEdit->text();
    m_scanButton->setEnabled(false);
    m_cancelButton->setEnabled(true);
    m_statusLabel->setText(tr("Scanning..."));

    auto *watcher = new QFutureWatcher<ScanResult>(this);
    connect(watcher, &QFutureWatcherBase::progressRangeChanged, m_progressBar, &QProgressBar::setRange);
    connect(watcher, &QFutureWatcherBase::progressValueChanged, m_progressBar, &QProgressBar::setValue);
    connect(m_cancelButton, &QPushButton::clicked, watcher, &QFutureWatcherBase::cancel);
    connect(watcher, &QFutureWatcherBase::finished, this, [this, watcher] {
        if (watcher->isCanceled()) {
            m_statusLabel->setText(tr("Canceled"));
        } else {
            const ScanResult result = watcher->result();
            m_statusLabel->setText(tr("%1 files, %2 duplicates").arg(result.files).arg(result.duplicates));
        }
        m_scanButton->setEnabled(true);
        m_cancelButton->setEnabled(false);
        watcher->deleteLater();
    });
    watcher->setFuture(QtConcurrent::run(scanDirectory, dir));
}
